    sorted_unique = sorted(set(nums))
    compress = {v: i+1 for i, v in enumerate(sorted_unique)}
    compressed = [compress[v] for v in nums]

    # Fenwick Tree implementation
    class FenwickTree:
        def __init__(self, size):
            self.n = size
            self.tree = [0] * (self.n + 1)

        def update(self, idx, delta=1):
            while idx <= self.n:
                self.tree[idx] += delta
                idx += idx & -idx

        def query(self, idx):
            res = 0
            while idx > 0:
                res += self.tree[idx]
                idx -= idx & -idx
            return res

    ft = FenwickTree(len(compressed))
    max_length = 0

    for num in reversed(compressed):
        # For each number, query the maximum length up to the previous smaller number
        length = ft.query(num - 1) + 1
        max_length = max(max_length, length)
        ft.update(num)

    return max_length
